package com.oneclickgoutweed;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class PatrolRecorderTest
{
	@Test
	public void plainFieldsAreJoined()
	{
		assertEquals("1,a,,2", PatrolRecorder.row(1, "a", null, 2));
	}

	@Test
	public void commasAndQuotesAreEscaped()
	{
		assertEquals("\"Search, Goutweed crate\",\"say \"\"oi\"\"\"",
			PatrolRecorder.row("Search, Goutweed crate", "say \"oi\""));
	}

	@Test
	public void headerHasOneColumnPerField()
	{
		assertEquals(17, PatrolRecorder.HEADER.split(",").length);
	}

	@Test
	public void storeroomBoundsAreInclusiveAndPlaneSpecific()
	{
		assertTrue(Storeroom.contains(new WorldPoint(2850, 10063, 0)));
		assertTrue(Storeroom.contains(new WorldPoint(2870, 10093, 0)));
		assertTrue(Storeroom.contains(new WorldPoint(2857, 10074, 0)));
		assertFalse(Storeroom.contains(new WorldPoint(2857, 10074, 1)));
		assertFalse(Storeroom.contains(new WorldPoint(2849, 10074, 0)));
		assertFalse(Storeroom.contains(null));
	}
}

package com.oneclickgoutweed;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class PatrolModelTest
{
	/** Gradle runs tests from the project root. */
	private static final String RECORDING = "analysis/recordings/patrol-20260926-002323.csv";

	@Test
	public void aGuardSeesItsTileAndTwoAheadOnly()
	{
		// One guard walking east along y = 0, loop x = 0..9 then back along y = 1.
		int[][] loop = new int[20][];
		for (int i = 0; i < 10; i++)
		{
			loop[i] = new int[]{i, 0};
			loop[19 - i] = new int[]{i, 1};
		}
		PatrolModel m = new PatrolModel(Collections.singletonMap(1, loop));
		assertTrue(m.observe(1, 3, 0, 100)); // at x=3 on tick 100, having stepped east

		assertEquals(Integer.valueOf(1), m.seenBy(100, 3, 0));
		assertEquals(Integer.valueOf(1), m.seenBy(100, 4, 0));
		assertEquals(Integer.valueOf(1), m.seenBy(100, 5, 0));
		assertNull(m.seenBy(100, 6, 0)); // three ahead
		assertNull(m.seenBy(100, 2, 0)); // behind
		assertNull(m.seenBy(100, 4, 1)); // diagonal
		assertEquals(Integer.valueOf(1), m.seenBy(101, 6, 0)); // it moved on
	}

	@Test
	public void offLoopSightingsAreIgnored()
	{
		PatrolModel m = new PatrolModel(GuardLoops.LOOPS);
		assertFalse(m.observe(4150, 0, 0, 5));
		assertTrue(m.unsynced().contains(4150));
	}

	/**
	 * The real test. For every departure along the route in the recording, the
	 * model sees only what had been observed before that tick, and must call
	 * the outcome the game actually gave.
	 */
	@Test
	public void predictsEveryRecordedAttempt() throws IOException
	{
		List<String[]> rows = new ArrayList<>();
		for (String line : Files.readAllLines(Paths.get(RECORDING), StandardCharsets.UTF_8))
		{
			rows.add(line.split(",", -1));
		}

		Map<Integer, int[]> me = new HashMap<>();
		List<int[]> sightings = new ArrayList<>(); // tick, id, x, y
		List<Integer> successes = new ArrayList<>();
		List<Integer> catches = new ArrayList<>();
		for (String[] r : rows.subList(1, rows.size()))
		{
			int tick = Integer.parseInt(r[0]);
			switch (r[2])
			{
				case "PLAYER":
					me.put(tick, new int[]{Integer.parseInt(r[6]), Integer.parseInt(r[7])});
					break;
				case "NPC":
					sightings.add(new int[]{tick, Integer.parseInt(r[4]), Integer.parseInt(r[6]), Integer.parseInt(r[7])});
					break;
				case "INVENTORY":
					successes.add(tick);
					break;
				case "OVERHEAD":
					if ("!".equals(r[r.length - 1]))
					{
						catches.add(tick);
					}
					break;
				default:
			}
		}

		int[] first = Route.TILES[0][0];
		int[] second = Route.TILES[1][0];
		int checked = 0;
		int predictedSafe = 0;
		for (int depart : new ArrayList<>(me.keySet()))
		{
			int[] a = me.get(depart);
			int[] b = me.get(depart + 1);
			if (b == null || a[0] != first[0] || a[1] != first[1] || b[0] != second[0] || b[1] != second[1])
			{
				continue;
			}

			boolean succeeded = within(successes, depart, depart + Route.TILES.length + 1);
			boolean caught = within(catches, depart, depart + Route.TILES.length + 1);
			assertTrue("departure " + depart + " has no recorded outcome", succeeded ^ caught);

			PatrolModel m = new PatrolModel(GuardLoops.LOOPS);
			for (int[] s : sightings)
			{
				if (s[0] < depart)
				{
					m.observe(s[1], s[2], s[3], s[0]);
				}
			}
			assertTrue("unsynced before " + depart + ": " + m.unsynced(), m.unsynced().isEmpty());
			assertEquals("departure " + depart, succeeded, m.safe(depart));
			checked++;
			predictedSafe += succeeded ? 1 : 0;
		}
		assertEquals("route departures in the recording", 10, checked);
		assertEquals("successes among them", 1, predictedSafe);
	}

	private static boolean within(List<Integer> ticks, int from, int to)
	{
		for (int t : ticks)
		{
			if (t >= from && t <= to)
			{
				return true;
			}
		}
		return false;
	}
}

package com.oneclickgoutweed;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class CompassTest
{
	@Test
	public void cardinalAndDiagonalPoints()
	{
		assertEquals("S", Compass.name(0));
		assertEquals("SW", Compass.name(256));
		assertEquals("W", Compass.name(512));
		assertEquals("NW", Compass.name(768));
		assertEquals("N", Compass.name(1024));
		assertEquals("NE", Compass.name(1280));
		assertEquals("E", Compass.name(1536));
		assertEquals("SE", Compass.name(1792));
	}

	@Test
	public void sectorEdgesRoundToNearest()
	{
		assertEquals("S", Compass.name(127));
		assertEquals("SW", Compass.name(128));
		assertEquals("S", Compass.name(2047));
		assertEquals("S", Compass.name(1920));
		assertEquals("SE", Compass.name(1919));
	}

	@Test
	public void outOfRangeWraps()
	{
		assertEquals("N", Compass.name(1024 + 2048));
	}

	@Test
	public void stepsPointTheSameWayAsNames()
	{
		assertArrayEquals(new int[]{0, -1}, Compass.step(0));
		assertArrayEquals(new int[]{-1, 0}, Compass.step(512));
		assertArrayEquals(new int[]{0, 1}, Compass.step(1024));
		assertArrayEquals(new int[]{1, 0}, Compass.step(1536));
		assertArrayEquals(new int[]{1, 1}, Compass.step(1280));
	}
}

