package com.oneclickgoutweed;

/**
 * The run from the start tile to the tile beside the crate, when you click
 * Search on the crate with run on. The game's pathfinder gives the same path
 * every time, measured in two recordings (2026-09-26, departures 352 and 237).
 *
 * TILES[i] holds every tile you touch i ticks after departing: where you end
 * the tick and, when running two tiles, the one you pass through. The
 * pass-through tile counts - one recorded catch is only explained by it.
 */
final class Route
{
	/** Stand here, facing anywhere, run on. */
	static final int START_X = 2862;
	static final int START_Y = 10092;

	/** The Search target, and the tile you finish on beside it. */
	static final int CRATE_X = 2857;
	static final int CRATE_Y = 10074;

	static final int[][][] TILES = {
		{{2860, 10092}, {2861, 10092}},
		{{2859, 10091}},
		{{2859, 10089}, {2859, 10090}},
		{{2859, 10087}, {2859, 10088}},
		{{2860, 10086}},
		{{2861, 10085}},
		{{2861, 10083}, {2861, 10084}},
		{{2861, 10081}, {2861, 10082}},
		{{2861, 10079}, {2861, 10080}},
		{{2861, 10077}, {2861, 10078}},
		{{2859, 10075}, {2860, 10076}},
		{{2858, 10074}},
	};

	private Route()
	{
	}
}

package com.oneclickgoutweed;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Debug view for the observation build: each guard's tile as the server has it,
 * a line three tiles long in the direction it faces, and a label with its index,
 * ID and compass point. Everything drawn comes from the last tick's snapshot.
 */
class ObservationOverlay extends Overlay
{
	private static final Color TILE = new Color(255, 200, 0);
	private static final Color FACING = new Color(255, 60, 60);
	private static final int FACING_TILES = 3;

	private final Client client;
	private final OneClickGoutweedPlugin plugin;
	private final OneClickGoutweedConfig config;

	@Inject
	ObservationOverlay(Client client, OneClickGoutweedPlugin plugin, OneClickGoutweedConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showDebugOverlay() || !plugin.isInStoreroom())
		{
			return null;
		}

		int plane = client.getTopLevelWorldView().getPlane();
		for (Sighting s : plugin.getSightings())
		{
			if (!s.isInStoreroom())
			{
				continue;
			}
			LocalPoint centre = s.getLocal();

			Polygon tile = Perspective.getCanvasTileAreaPoly(client, centre, s.getSize());
			if (tile != null)
			{
				OverlayUtil.renderPolygon(graphics, tile, TILE);
			}

			int[] d = Compass.step(s.getOrientation());
			int reach = FACING_TILES * Perspective.LOCAL_TILE_SIZE;
			Point from = Perspective.localToCanvas(client, centre, plane);
			Point to = Perspective.localToCanvas(client, centre.plus(d[0] * reach, d[1] * reach), plane);
			if (from != null && to != null)
			{
				graphics.setColor(FACING);
				graphics.setStroke(new BasicStroke(2));
				graphics.drawLine(from.getX(), from.getY(), to.getX(), to.getY());
			}

			String label = "#" + s.getNpc().getIndex() + " " + s.getNpc().getId() + " " + Compass.name(s.getOrientation());
			Point text = Perspective.getCanvasTextLocation(client, graphics, centre, label, 0);
			if (text != null)
			{
				OverlayUtil.renderTextLocation(graphics, text, label, TILE);
			}
		}

		String file = plugin.getRecordingFile();
		String status = "tick " + client.getTickCount() + (file == null ? "  not recording" : "  REC " + file);
		OverlayUtil.renderTextLocation(graphics, new Point(10, 20), status, file == null ? Color.WHITE : FACING);
		return null;
	}
}

