/**
 * In the scene: the start tile, always, and the crate, green on the tick to click.
 * Drawing only - it changes no menu and no click zone.
 */
class CueOverlay extends Overlay
{
	static final Color GO = new Color(40, 220, 40);
	static final Color READY = new Color(255, 200, 0);
	static final Color NOT_READY = new Color(255, 90, 60);

	private final Client client;
	private final OneClickGoutweedPlugin plugin;

	@Inject
	CueOverlay(Client client, OneClickGoutweedPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Cue cue = plugin.getCue();
		if (cue.getState() == Cue.State.NONE)
		{
			return null;
		}

		// The start tile: red until you're on it, amber while waiting, green to go.
		Color start = cue.getState() == Cue.State.CLICK ? GO
			: cue.getState() == Cue.State.NOT_ON_START ? NOT_READY
			: READY;
		LocalPoint lp = LocalPoint.fromWorld(client.getTopLevelWorldView(),
			new WorldPoint(Route.START_X, Route.START_Y, Storeroom.PLANE));
		if (lp != null)
		{
			Polygon tile = Perspective.getCanvasTilePoly(client, lp);
			if (tile != null)
			{
				OverlayUtil.renderPolygon(graphics, tile, start);
			}
		}

		TileObject crate = plugin.getCrate();
		if (cue.getState() == Cue.State.CLICK && crate != null)
		{
			Shape box = crate.getClickbox();
			if (box != null)
			{
				OverlayUtil.renderHoverableArea(graphics, box, client.getMouseCanvasPosition(),
					new Color(GO.getRed(), GO.getGreen(), GO.getBlue(), 80), GO, GO);
			}
		}
		return null;
	}
}

package com.oneclickgoutweed;

import java.io.BufferedWriter;
import java.io.IOException;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Writes the patrol log to disk without the client thread ever touching the disk.
 *
 * The split: the plugin reads game state on the client thread (the only thread
 * where that's safe) and turns it into finished text. This class hands the text
 * to RuneLite's shared executor, which is a single thread, so rows land in the
 * order they were submitted and the writer below is only ever touched by that
 * one thread - no locks needed.
 */
@Slf4j
@Singleton
class PatrolRecorder
{
	static final String HEADER = row("tick", "ms", "type", "index", "id", "name", "x", "y", "plane", "size",
		"orientation", "facing", "current_orientation", "animation", "pose_animation", "interacting", "detail");

	private final ScheduledExecutorService executor;

	/** Executor thread only. Null when no file is open, or after a write failed. */
	private BufferedWriter out;

	/**
	 * Name of the file actually open, for the overlay. Set only after the open
	 * succeeds, so "REC" on screen means a file really exists - not merely that
	 * one was asked for.
	 */
	@Getter
	private volatile String openFile;

	@Inject
	PatrolRecorder(ScheduledExecutorService executor)
	{
		this.executor = executor;
	}

	/**
	 * Opens a new file in the plugin's data directory. Runs on the executor
	 * because every step touches the disk.
	 */
	void start(Callable<Filepath> directory, String fileName)
	{
		executor.execute(() ->
		{
			closeQuietly();
			try
			{
				// getPluginDirectory() creates plugin-data/ but not this plugin's
				// own folder inside it. Found in game 2026-09-26: NoSuchFileException.
				Filepath dir = directory.call();
				dir.createDirectories();
				Filepath file = dir.joinSegment(fileName);
				out = file.openBufferedWriter();
				out.write(HEADER);
				out.newLine();
				openFile = fileName;
				log.info("Recording goutweed patrol to {}", file);
			}
			catch (Exception e)
			{
				log.warn("Could not open patrol log {}", fileName, e);
				out = null;
			}
		});
	}

	void write(List<String> rows)
	{
		executor.execute(() ->
		{
			if (out == null)
			{
				return;
			}
			try
			{
				for (String r : rows)
				{
					out.write(r);
					out.newLine();
				}
				// Once per tick. Cheap, and a crash loses at most the tick in flight.
				out.flush();
			}
			catch (IOException e)
			{
				log.warn("Patrol log write failed; recording stopped", e);
				closeQuietly();
			}
		});
	}

	/** Safe from any thread: it only queues the close. */
	void stop()
	{
		executor.execute(this::closeQuietly);
	}

	private void closeQuietly()
	{
		openFile = null;
		if (out == null)
		{
			return;
		}
		try
		{
			out.close();
		}
		catch (IOException e)
		{
			log.warn("Patrol log close failed", e);
		}
		out = null;
	}

	/** One CSV row. Fields holding a comma, quote or newline are quoted, with quotes doubled. */
	static String row(Object... fields)
	{
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < fields.length; i++)
		{
			if (i > 0)
			{
				sb.append(',');
			}
			String s = fields[i] == null ? "" : fields[i].toString();
			if (s.indexOf(',') >= 0 || s.indexOf('"') >= 0 || s.indexOf('\n') >= 0 || s.indexOf('\r') >= 0)
			{
				sb.append('"').append(s.replace("\"", "\"\"")).append('"');
			}
			else
			{
				sb.append(s);
			}
		}
		return sb.toString();
	}
}

