import net.runelite.api.coords.WorldPoint;

/**
 * One NPC as the server had it on one tick. The overlay draws this rather than
 * the NPC's live position, so the outline shows the true tile, not the smoothed walk.
 */
@Value
class Sighting
{
	NPC npc;
	/** Centre of the NPC's server-side footprint, scene coordinates. */
	LocalPoint local;
	/** South-west tile of the footprint. */
	WorldPoint world;
	int size;
	int orientation;
	boolean inStoreroom;
}

package com.oneclickgoutweed;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

/**
 * Predicts every guard's tile on any future tick, and whether the run to the
 * crate is safe for a given departure tick.
 *
 * Pure Java, no game API: the plugin feeds it observations, and the tests feed
 * it a recording. That split is what lets the prediction be tested against
 * real attempts without a client.
 *
 * The idea: each guard walks a fixed loop, one tile per tick, and no tile
 * repeats within a loop. So a single sighting fixes the guard's phase - which
 * loop index it's at on tick 0 - and from then on its tile on tick t is
 * loop[(phase + t) mod length]. It's the same arithmetic as a clock hand.
 */
final class PatrolModel
{
	private final Map<Integer, int[][]> loops;

	/** Guard ID -> loop index on tick 0. Absent until the guard has been seen. */
	private final Map<Integer, Integer> phase = new HashMap<>();

	PatrolModel(Map<Integer, int[][]> loops)
	{
		this.loops = loops;
	}

	/**
	 * Re-syncs a guard from where it stands now. Every sighting overwrites the
	 * phase, so a guard that paused to throw a rock is corrected the next time
	 * it's seen instead of drifting.
	 *
	 * @return false if the tile isn't on that guard's loop (not a patroller,
	 *         or knocked off its path), in which case nothing changes
	 */
	boolean observe(int id, int x, int y, int tick)
	{
		int[][] loop = loops.get(id);
		if (loop == null)
		{
			return false;
		}
		for (int i = 0; i < loop.length; i++)
		{
			if (loop[i][0] == x && loop[i][1] == y)
			{
				phase.put(id, Math.floorMod(i - tick, loop.length));
				return true;
			}
		}
		return false;
	}

	/** Guards never seen yet. Until this is empty, no prediction is trustworthy. */
	Set<Integer> unsynced()
	{
		Set<Integer> out = new TreeSet<>(loops.keySet());
		out.removeAll(phase.keySet());
		return out;
	}

	void reset()
	{
		phase.clear();
	}

	int[] tileAt(int id, int tick)
	{
		int[][] loop = loops.get(id);
		return loop[Math.floorMod(phase.get(id) + tick, loop.length)];
	}

	/**
	 * The guard that sees tile (x, y) on this tick, or null. A guard sees its own
	 * tile and the two tiles straight ahead in the direction of its last step.
	 * Fitted to 11 of 11 catches, with no false catches across 38 near misses.
	 */
	Integer seenBy(int tick, int x, int y)
	{
		for (int id : loops.keySet())
		{
			int[] now = tileAt(id, tick);
			int[] before = tileAt(id, tick - 1);
			int dx = now[0] - before[0];
			int dy = now[1] - before[1];
			for (int k = 0; k <= 2; k++)
			{
				if (now[0] + k * dx == x && now[1] + k * dy == y)
				{
					return id;
				}
			}
		}
		return null;
	}

	/** Whether leaving the start tile on {@code depart} reaches the crate unseen. */
	boolean safe(int depart)
	{
		for (int i = 0; i < Route.TILES.length; i++)
		{
			for (int[] tile : Route.TILES[i])
			{
				if (seenBy(depart + i, tile[0], tile[1]) != null)
				{
					return false;
				}
			}
		}
		return true;
	}

	/**
	 * Whether a click during tick {@code now} is safe. A click lands the first
	 * step on now + 1 if it reaches the server in time, or on now + 2 if it's
	 * late in the tick. With {@code margin} set, both must be safe, so where in
	 * the tick you click doesn't matter. Without it, only now + 1 is checked.
	 */
	boolean clickSafe(int now, boolean margin)
	{
		return safe(now + 1) && (!margin || safe(now + 2));
	}

	/** Ticks from {@code now} until clicking is safe; 0 means now, -1 means not within the horizon. */
	int ticksUntilClick(int now, boolean margin, int horizon)
	{
		for (int k = 0; k <= horizon; k++)
		{
			if (clickSafe(now + k, margin))
			{
				return k;
			}
		}
		return -1;
	}
}

package com.oneclickgoutweed;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/** The countdown box. Text only; reads the tick's cue and formats it. */
class CuePanel extends OverlayPanel
{
	private final OneClickGoutweedPlugin plugin;

	@Inject
	CuePanel(OneClickGoutweedPlugin plugin)
	{
		super(plugin);
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Cue cue = plugin.getCue();
		String text;
		Color colour;
		switch (cue.getState())
		{
			case NONE:
				return null;
			case WATCHING:
				text = "Watching guards (" + cue.getTicks() + " unseen)";
				colour = CueOverlay.READY;
				break;
			case NOT_ON_START:
				text = "Stand on the marked tile";
				colour = CueOverlay.NOT_READY;
				break;
			case RUN_OFF:
				text = "Turn run on";
				colour = CueOverlay.NOT_READY;
				break;
			case NO_WINDOW:
				text = "No safe window soon";
				colour = CueOverlay.NOT_READY;
				break;
			case CLICK:
				text = "CLICK the crate";
				colour = CueOverlay.GO;
				break;
			case WAIT:
			default:
				// Whole ticks, plus seconds for a sense of how long to look away.
				text = "Click in " + cue.getTicks() + String.format(" (%.1fs)", cue.getTicks() * 0.6);
				colour = CueOverlay.READY;
				break;
		}
		panelComponent.getChildren().add(TitleComponent.builder().text("Goutweed").build());
		panelComponent.getChildren().add(LineComponent.builder().left(text).leftColor(colour).build());
		return super.render(graphics);
	}
}

package com.oneclickgoutweed;

import lombok.Value;

/** What to tell the player this tick. Built once per tick, read every frame. */
@Value
class Cue
{
	enum State
	{
		/** Not in the storeroom: draw nothing. */
		NONE,
		/** Some guard hasn't been seen yet, so its position can't be predicted. */
		WATCHING,
		/** Not on the start tile, which the route is measured from. */
		NOT_ON_START,
		/** Run is off or nearly out; the route assumes running the whole way. */
		RUN_OFF,
		/** No safe click within the horizon. */
		NO_WINDOW,
		/** A safe click is coming; {@link #ticks} until it. */
		WAIT,
		/** Clicking Search during this tick is safe. */
		CLICK
	}

	static final Cue NONE = new Cue(State.NONE, 0);

	State state;
	/** WAIT: ticks until the click. WATCHING: guards still unseen. */
	int ticks;
}
